    _bounded(value)
    versions = {"ContentPackage":("content_package_version",1), "Selection":("selection_version",1),
                "Preset":("preset_version",1), "Manifest":("manifest_version",2), "Catalog":("catalog_version",1),
                "CatalogFiles":("catalog_files_version",1), "Subset":("schema_version",3), "Files":("schema_version",2),
                "Build":("schema_version",2), "Lock":("lock_version",2), "EngineBundle":("engine_package_version",1)}
    if kind in versions and type(value) is dict:
        field, expected = versions[kind]
        if field in value:
            require(type(value[field]) is int, "invalid exact discriminator type")
            if value[field] != expected: raise DistributionError("unsupported-version: unknown " + kind)
    def check(spec, item):
        if "$ref" in spec:
            ref = spec["$ref"]
            require(ref.startswith("#/$defs/"), "invalid internal schema reference")
            return check(DEFINITIONS[ref[8:]], item)
        if "anyOf" in spec:
            from .data import DistributionError
            for arm in spec["anyOf"]:
                try:
                    check(arm, item)
                    return
                except DistributionError:
                    pass
            require(False, kind + ": invalid union")
        if "const" in spec:
            require(type(item) is type(spec["const"]) and item == spec["const"], kind + ": unsupported-version or constant")
        if "enum" in spec:
            require(any(type(item) is type(v) and item == v for v in spec["enum"]), kind + ": unsupported enum")
        typ = spec.get("type")
        types = {"object":dict,"array":list,"string":str,"integer":int,"boolean":bool,"null":type(None)}
        if typ:
            require(type(item) is types[typ], kind + ": invalid exact type")
        if typ == "object":
            require(set(spec["required"]) <= item.keys() <= spec["properties"].keys(), kind + ": missing/unknown fields")
            for key, child in item.items(): check(spec["properties"][key], child)
        elif typ == "array":
            require(spec.get("minItems",0) <= len(item) <= min(spec.get("maxItems",4096),4096), kind + ": array budget")
            if spec.get("uniqueItems"):
                keys=[json_bytes(x) for x in item]
                require(len(keys)==len(set(keys)), kind + ": duplicate rows")
            for child in item: check(spec["items"], child)
        elif typ == "string":
            item.encode("utf-8", errors="strict")
            require(spec.get("minLength",0) <= len(item) <= spec.get("maxLength",4096), kind + ": string budget")
            if "pattern" in spec: require(re.fullmatch(spec["pattern"],item) is not None, kind + ": lexical grammar")
            if spec.get("format") == "date-time":
                require(datetime.fromisoformat(item).utcoffset() is not None, kind + ": timestamp offset required")
        elif typ == "integer":
            require(spec.get("minimum",0) <= item <= spec.get("maximum",16*1024*1024), kind + ": integer budget")
    check(DEFINITIONS[kind],value)
    return value
